import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long carry = 0, answer = 0;
        for (int i = 0; i < n; i++) {
            long total = nextLong() + carry;
            answer += total % 2;
            carry = total / 2;
        }
        // past the end, every set bit of the carry leaves one single block
        System.out.println(answer + Long.bitCount(carry));
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	carry, answer := 0, 0
	for i := 0; i < n; i++ {
		total := next() + carry
		answer += total % 2
		carry = total / 2
	}
	// past the end, every set bit of the carry leaves one single block
	fmt.Println(answer + bits.OnesCount64(uint64(carry)))
}
